# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_API_ID=}"
: "${MDF_BEARER_TOKEN?MDF_BEARER_TOKEN is required (Azure parameter bearerToken)}"
: "${MDF_BG_ID=}"
: "${MDF_CLIENT_APP_ID?MDF_CLIENT_APP_ID is required (Azure parameter clientAppId)}"
: "${MDF_CONTRACTS_PATH?MDF_CONTRACTS_PATH is required (Azure parameter contractsPath)}"
: "${MDF_ENV_ID=}"

# >>> extracted body
BG_ID="${MDF_BG_ID}"
ENV_ID="${MDF_ENV_ID}"
CONTRACTS_PATH="${MDF_CONTRACTS_PATH}"
CLIENT_APP_ID="${MDF_CLIENT_APP_ID}"
RESOLVED_API_ID="${MDF_API_ID}"

echo "[DEBUG] ============================================"
echo "[DEBUG] CREATE CONTRACTS"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   envId=$ENV_ID"
echo "[DEBUG]   contractsPath=$CONTRACTS_PATH"
echo "[DEBUG]   clientAppId=$CLIENT_APP_ID"
echo "[DEBUG] ============================================"

if [ ! -d "$CONTRACTS_PATH" ]; then
  echo "[DEBUG] Contracts folder NOT FOUND: $CONTRACTS_PATH"
  ci_log_warning "Contracts folder not found: $CONTRACTS_PATH. Skipping."
  exit 0
fi

CONTRACT_FILES=$(find "$CONTRACTS_PATH" -maxdepth 1 -type f -name "*.json" | sort)

if [ -z "$CONTRACT_FILES" ]; then
  echo "[DEBUG] No *.json files in $CONTRACTS_PATH"
  echo "No contract files found. Skipping."
  exit 0
fi

echo "Found contract files: $(echo "$CONTRACT_FILES" | xargs -n 1 basename)"

for CONTRACT_FILE in $CONTRACT_FILES; do
  CONTENT=$(cat "$CONTRACT_FILE")

  # Update org and env IDs to match target environment
  CONTENT=$(echo "$CONTENT" | jq --arg org "$BG_ID" --arg env "$ENV_ID" \
    '.organizationId = $org | .environmentId = $env | .groupId = $org')

  # Resolve apiId: an unresolved ${...} placeholder (or empty) is replaced with
  # the API Manager instance ID passed from the pipeline (single-API case).
  RAW_API_ID=$(echo "$CONTENT" | jq -r '.apiId // empty')
  if [[ -z "$RAW_API_ID" || "$RAW_API_ID" == *'${'* ]]; then
    if [[ -n "$RESOLVED_API_ID" ]]; then
      CONTENT=$(echo "$CONTENT" | jq --arg aid "$RESOLVED_API_ID" '.apiId = $aid')
      echo "[DEBUG] Resolved contract apiId placeholder ('$RAW_API_ID') to: $RESOLVED_API_ID"
    else
      ci_log_error "Contract apiId is unresolved ('$RAW_API_ID') and no apiId was provided to resolve it."
      exit 1
    fi
  fi

  # Resolve tier name to tier ID if requestedTierId is a string name
  TIER_VALUE=$(echo "$CONTENT" | jq -r '.requestedTierId // empty')
  API_ID=$(echo "$CONTENT" | jq -r '.apiId')

  if [[ -n "$TIER_VALUE" && ! "$TIER_VALUE" =~ ^[0-9]+$ ]]; then
    echo "  Resolving tier name '$TIER_VALUE' to ID..."

    tier_response=$(curl -s --location \
      "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/tiers?query=${TIER_VALUE}" \
      --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")

    TIER_ID=$(echo "$tier_response" | jq -r '.tiers[0].id // empty')

    if [[ -z "$TIER_ID" ]]; then
      ci_log_error "Could not resolve tier '$TIER_VALUE' for API $API_ID."
      exit 1
    fi

    CONTENT=$(echo "$CONTENT" | jq --argjson tid "$TIER_ID" '.requestedTierId = $tid')
  fi

  echo "[DEBUG] Processing contract file: $(basename "$CONTRACT_FILE")"
  echo "[DEBUG] API_ID=$API_ID, TIER_VALUE=$TIER_VALUE"
  echo "[DEBUG] Contract payload (org/env updated): $(echo "$CONTENT" | jq -c '.')"
  echo "Creating contract for API: $API_ID"

  create_response=$(curl -i -s --location \
    "https://anypoint.mulesoft.com/exchange/api/v2/organizations/${BG_ID}/applications/${CLIENT_APP_ID}/contracts" \
    --header "Content-Type: application/json" \
    --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
    --data "$CONTENT")

  HTTP_STATUS=$(echo "$create_response" | head -n 1 | awk '{print $2}')
  BODY=$(echo "$create_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)

  if [[ "$HTTP_STATUS" == "201" ]]; then
    echo "  Contract created successfully."
  elif [[ "$HTTP_STATUS" == "409" ]]; then
    echo "  Contract already exists."
  else
    ci_log_error "Failed to create contract. Status: $HTTP_STATUS"
    echo "Response: $BODY"
    exit 1
  fi
done

echo "Contract creation completed."
echo "[DEBUG] CREATE CONTRACTS COMPLETE"
